import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'fs';
import { randomUUID } from 'crypto';
import * as path from 'path';

/**
 * God's Land stage 5 (docs/product-reset/gods-land/03_PLAN.md): the smart clipboard. The helper sees a copy (when the
 * person turned history on, and never a password manager's — nspasteboard.org Concealed/Transient/AutoGenerated); this
 * decides what the copy IS and what it can become, and keeps the history. Everything here runs on the Mac: no model is
 * asked, nothing is sent anywhere.
 *
 * - colour  → hex, rgb(), hsl(), SwiftUI Color, and the nearest Tailwind class;
 * - JSON    → minified, pretty, and a TypeScript type (inferred here, deterministically);
 * - link    → the same link without tracking parameters (our own list, research 02 §4: ClearURLs' is LGPL);
 * - code    → its language, and one line for shell and SQL;
 * - anything that looks like a secret key is NOT kept at all until stage 6 can mask it (looksSecret).
 * Ghost Paste is not here: the owner dropped it (03, decision 1).
 */

export type ClipKind = 'color' | 'json' | 'url' | 'code' | 'text';
export interface ClipAction { label: string; value: string }
export interface ClipCard { id: string; kind: ClipKind; preview: string; text: string; detail?: string; swatch?: string; actions: ClipAction[]; pinned: boolean; source?: string }
export interface ClipView { t: 'clips'; enabled: boolean; items: ClipCard[] }

// ── Colours ──────────────────────────────────────────────────────────────────────────────────────────────────────────

export interface Rgb { r: number; g: number; b: number; a: number }

const clamp = (x: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, x));
const hex2 = (n: number): string => Math.round(clamp(n, 0, 255)).toString(16).padStart(2, '0');
const alphaOf = (raw: string | undefined): number => (raw === undefined ? 1 : clamp(raw.endsWith('%') ? parseFloat(raw) / 100 : parseFloat(raw), 0, 1));

export function parseColor(text: string): Rgb | null {
  const t = text.trim().toLowerCase();
  let m = /^#([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/.exec(t);
  if (m) {
    let h = m[1]!;
    if (h.length === 3) h = h.split('').map((c) => c + c).join('');
    const a = h.length === 8 ? parseInt(h.slice(6, 8), 16) / 255 : 1;
    return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16), a };
  }
  m = /^rgba?\(\s*(\d{1,3})\s*[, ]\s*(\d{1,3})\s*[, ]\s*(\d{1,3})\s*(?:[,/]\s*([\d.]+%?)\s*)?\)$/.exec(t);
  if (m) {
    const [r, g, b] = [m[1], m[2], m[3]].map(Number) as [number, number, number];
    if (r > 255 || g > 255 || b > 255) return null;
    return { r, g, b, a: alphaOf(m[4]) };
  }
  m = /^hsla?\(\s*([\d.]+)(?:deg)?\s*[, ]\s*([\d.]+)%\s*[, ]\s*([\d.]+)%\s*(?:[,/]\s*([\d.]+%?)\s*)?\)$/.exec(t);
  if (m) {
    const h = (parseFloat(m[1]!) % 360) / 360;
    const s = clamp(parseFloat(m[2]!) / 100, 0, 1);
    const l = clamp(parseFloat(m[3]!) / 100, 0, 1);
    const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
    const p = 2 * l - q;
    const f = (x: number): number => {
      const y = ((x % 1) + 1) % 1;
      return y < 1 / 6 ? p + (q - p) * 6 * y : y < 1 / 2 ? q : y < 2 / 3 ? p + (q - p) * (2 / 3 - y) * 6 : p;
    };
    return { r: Math.round(f(h + 1 / 3) * 255), g: Math.round(f(h) * 255), b: Math.round(f(h - 1 / 3) * 255), a: alphaOf(m[4]) };
  }
  return null;
}

export function toHex(c: Rgb): string { return `#${hex2(c.r)}${hex2(c.g)}${hex2(c.b)}${c.a < 1 ? hex2(c.a * 255) : ''}`; }
export function toRgb(c: Rgb): string { return c.a < 1 ? `rgb(${c.r} ${c.g} ${c.b} / ${+c.a.toFixed(2)})` : `rgb(${c.r}, ${c.g}, ${c.b})`; }
export function toHsl(c: Rgb): string {
  const r = c.r / 255, g = c.g / 255, b = c.b / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2, d = max - min;
  let h = 0, s = 0;
  if (d) {
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
    h *= 60;
  }
  return `hsl(${Math.round(h)} ${Math.round(s * 100)}% ${Math.round(l * 100)}%${c.a < 1 ? ` / ${+c.a.toFixed(2)}` : ''})`;
}
export function toSwiftUI(c: Rgb): string {
  const f = (n: number): string => { const v = +(n / 255).toFixed(3); return Number.isInteger(v) ? v.toFixed(1) : String(v); };
  return `Color(red: ${f(c.r)}, green: ${f(c.g)}, blue: ${f(c.b)}${c.a < 1 ? `, opacity: ${+c.a.toFixed(2)}` : ''})`;
}

