const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];

/** The nearest Tailwind colour class (a redmean distance, closer to the eye than plain RGB); exact when in the palette. */
export function nearestTailwind(c: Rgb): { name: string; exact: boolean } {
  let best = { name: '', distance: Infinity };
  for (const [family, hexes] of Object.entries(TAILWIND)) {
    hexes.forEach((hex, i) => {
      const p = parseColor(hex)!;
      const rMean = (p.r + c.r) / 2;
      const distance = (2 + rMean / 256) * (p.r - c.r) ** 2 + 4 * (p.g - c.g) ** 2 + (2 + (255 - rMean) / 256) * (p.b - c.b) ** 2;
      if (distance < best.distance) best = { name: `${family}-${SHADES[i]}`, distance };
    });
  }
  return { name: best.name, exact: best.distance === 0 };
}

// ── Links ────────────────────────────────────────────────────────────────────────────────────────────────────────────

/** Parameters that only track the click. Our own list: well-known, generic, and not ClearURLs' (LGPL, 02 §4). */
const TRACKING = new Set([
  'fbclid', 'gclid', 'dclid', 'gbraid', 'wbraid', 'msclkid', 'yclid', 'twclid', 'ttclid', 'li_fat_id', 'igshid', 'igsh',
  'mc_cid', 'mc_eid', '_hsenc', '_hsmi', 'hsctatracking', 'mkt_tok', 'vero_id', 'vero_conv', 'oly_anon_id', 'oly_enc_id',
  'rb_clickid', 's_cid', 'ncid', 'sr_share', 'spm', 'scm', 'si', 'ref_src', 'ref_url', 'trk', 'trkcampaign',
]);

/** The link without tracking parameters, or null when there was nothing to remove. Non-http(s) links are left alone. */
export function cleanUrl(text: string): string | null {
  let url: URL;
  try { url = new URL(text.trim()); } catch { return null; }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
  const drop = [...url.searchParams.keys()].filter((k) => TRACKING.has(k.toLowerCase()) || /^utm_/i.test(k) || /^pk_/i.test(k));
  if (!drop.length) return null;
  for (const key of drop) url.searchParams.delete(key);
  return url.toString().replace(/\?$/, '').replace(/\?#/, '#');
}

// ── JSON → TypeScript ───────────────────────────────────────────────────────────────────────────────────────────────

const IDENT = /^[A-Za-z_$][\w$]*$/;
const pascal = (key: string): string =>
  key.replace(/[^A-Za-z0-9]+(.)?/g, (_: string, c: string | undefined) => (c ? c.toUpperCase() : '')).replace(/^./, (c) => c.toUpperCase()) || 'Item';

/** A TypeScript type for a JSON value: nested objects become named interfaces, arrays merge their elements' shapes. */
export function jsonToTypeScript(value: unknown, rootName = 'Root'): string {
  const interfaces: string[] = [];
  const used = new Set<string>();
  const nameFor = (base: string): string => { let n = base; let i = 2; while (used.has(n)) n = `${base}${i++}`; used.add(n); return n; };
  const objectType = (fields: Record<string, unknown[]>, count: number, base: string): string => {
    const name = nameFor(pascal(base));
    const lines = Object.entries(fields).map(([key, values]) => {
      const types = [...new Set(values.map((x) => typeOf(x, key)))];
      return `  ${IDENT.test(key) ? key : JSON.stringify(key)}${values.length < count ? '?' : ''}: ${types.join(' | ')};`;
    });
    interfaces.push(`export interface ${name} {\n${lines.join('\n')}\n}`);
    return name;
  };
  const typeOf = (v: unknown, name: string): string => {
    if (v === null) return 'null';
    if (Array.isArray(v)) {
      if (!v.length) return 'unknown[]';
      if (v.every((e) => e && typeof e === 'object' && !Array.isArray(e))) {
        const merged: Record<string, unknown[]> = {};
        for (const e of v as Record<string, unknown>[]) for (const [k, x] of Object.entries(e)) (merged[k] ??= []).push(x);
        return `${objectType(merged, v.length, name.replace(/s$/, '') || name)}[]`;
      }
      const types = [...new Set(v.map((e) => typeOf(e, name)))];
      return types.length === 1 ? `${types[0]}[]` : `(${types.join(' | ')})[]`;
    }
    if (typeof v === 'object') return objectType(Object.fromEntries(Object.entries(v as object).map(([k, x]) => [k, [x]])), 1, name);
    return typeof v === 'number' || typeof v === 'boolean' || typeof v === 'string' ? typeof v : 'unknown';
  };
  const root = typeOf(value, rootName);
  const out = [...interfaces];
  if (root !== pascal(rootName)) out.push(`export type ${nameFor(rootName)} = ${root};`);
  return out.join('\n\n');
}

// ── Code ─────────────────────────────────────────────────────────────────────────────────────────────────────────────

const LANGUAGES: Array<[string, RegExp]> = [
  ['SQL', /^\s*(select\s[\s\S]+\sfrom\s|insert\s+into\s|update\s+\w+\s+set\s|delete\s+from\s|create\s+(table|index|view)\s)/i],
  ['Shell', /^\s*(\$\s|sudo\s|brew\s|npm\s|npx\s|pnpm\s|yarn\s|git\s|cd\s|ls\b|curl\s|docker\s|kubectl\s|export\s+\w+=|pip3?\s|python3?\s+-m\s|chmod\s|mkdir\s)/],
  ['Swift', /\b(import (SwiftUI|Foundation|AppKit|UIKit)|guard let |func \w+\(.*\)\s*->\s*\w+\s*\{)/],
  ['Rust', /\b(fn \w+\(|let mut |impl\s+\w+|pub fn |use std::)/],
  ['Go', /\b(package main|func \w+\(.*\)\s*\{|:= |import \()/],
  ['Python', /^\s*(def \w+\(.*\):|class \w+.*:|import \w+\s*$|from \w+ import )/m],
  ['TypeScript', /\b(interface \w+\s*\{|type \w+ =|: (string|number|boolean)\b|as const\b)/],
  ['JavaScript', /\b(function \w*\(|const \w+ = |let \w+ = |=>\s*\{|console\.log\(|require\()/],
  ['C/C++', /#include\s*[<"]|\bint main\(|std::/],
  ['HTML', /^\s*<(!doctype|html|div|span|a |p>|section|head|body)/i],
  ['CSS', /^[\s.#\w-]+\{[^}]*:[^}]*;[^}]*\}/],
];

export function codeLanguage(text: string): string | null {
  const t = text.trim();
  if (t.length < 4) return null;
  for (const [name, pattern] of LANGUAGES) if (pattern.test(t)) return name;
  return null;
}

/** One line for shell (backslash continuations and lines joined with &&) and SQL (whitespace collapsed). */
export function oneLine(text: string, language: string): string | null {
  const t = text.trim();
  if (!t.includes('\n')) return null;
  if (language === 'Shell') return t.replace(/[ \t]*\\\n\s*/g, ' ').split('\n').map((l) => l.trim().replace(/^\$\s+/, '')).filter(Boolean).join(' && ');
  if (language === 'SQL') return t.replace(/\s+/g, ' ');
  return null;
}

// ── Secrets (kept out until stage 6) ────────────────────────────────────────────────────────────────────────────────

/** The most common credential shapes (after gitleaks' rules, MIT): these are not kept in the history at all. */
const SECRET = [
  /\bAKIA[0-9A-Z]{16}\b/, /\b(sk|pk|rk)_(live|test)_[0-9A-Za-z]{16,}\b/, /\bgh[pousr]_[A-Za-z0-9]{36,}\b/, /\bgithub_pat_[A-Za-z0-9_]{50,}\b/,
  /\bxox[abpors]-[A-Za-z0-9-]{10,}\b/, /-----BEGIN (RSA |EC |OPENSSH |DSA |PGP )?PRIVATE KEY-----/, /\bAIza[0-9A-Za-z_-]{35}\b/,
  /\bsk-(proj-|ant-)?[A-Za-z0-9_-]{20,}\b/, /\bnvapi-[A-Za-z0-9_-]{20,}\b/, /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/,
  /\b[a-z][a-z0-9+.-]*:\/\/[^\s:/@]+:[^\s@/]{3,}@/i,
];
export function looksSecret(text: string): boolean { return SECRET.some((p) => p.test(text)); }

// ── What a copy is ───────────────────────────────────────────────────────────────────────────────────────────────────

export function classify(text: string): Omit<ClipCard, 'id' | 'pinned' | 'source'> {
  const t = text.trim();
  const first = t.split('\n')[0]!;
  const preview = first.slice(0, 80) + (t.length > first.length || first.length > 80 ? '…' : '');
  const color = parseColor(t);
  if (color) {
    const tw = nearestTailwind(color);
    return { kind: 'color', preview: t, text, swatch: toHex(color), detail: tw.exact ? tw.name : `≈ ${tw.name}`, actions: [
      { label: 'HEX', value: toHex(color) }, { label: 'RGB', value: toRgb(color) }, { label: 'HSL', value: toHsl(color) },
      { label: 'Swift', value: toSwiftUI(color) }, { label: tw.exact ? 'Tailwind' : 'Tailwind ≈', value: `bg-${tw.name}` },
    ] };
  }
  if (/^[[{]/.test(t)) {
    try {
      const value = JSON.parse(t) as unknown;
      if (value && typeof value === 'object') {
        const count = Array.isArray(value) ? `${value.length} items` : `${Object.keys(value).length} keys`;
        return { kind: 'json', preview, text, detail: `JSON · ${count}`, actions: [
          { label: 'Minify', value: JSON.stringify(value) }, { label: 'Pretty', value: JSON.stringify(value, null, 2) },
          { label: 'TS type', value: jsonToTypeScript(value) },
        ] };
      }
    } catch { /* not JSON */ }
  }
  if (/^https?:\/\/\S+$/i.test(t)) {
    let host = '';
    try { host = new URL(t).hostname; } catch { /* kept as text */ }
    if (host) {
      const cleaned = cleanUrl(t);
      return { kind: 'url', preview: t.slice(0, 80), text, detail: cleaned ? `${host} · tracking removed` : host, actions: cleaned ? [{ label: 'Clean link', value: cleaned }] : [] };
    }
  }
  const language = codeLanguage(t);
  if (language) {
    const single = oneLine(t, language);
    return { kind: 'code', preview, text, detail: language, actions: single ? [{ label: 'One line', value: single }] : [] };
  }
  return { kind: 'text', preview, text, actions: [] };
}

// ── The history ─────────────────────────────────────────────────────────────────────────────────────────────────────

export const MAX_CLIPS = 50;
export const MAX_CLIP_CHARS = 20_000;
export const CLIPS_SHOWN = 12;
interface StoredClip { id: string; text: string; at: number; pinned?: boolean; source?: string }

/**
 * The last MAX_CLIPS copies, newest first, pinned ones kept past the limit. Saved on this Mac only, in the app's data
 * folder. Unlike the shelf this is a history: the oldest unpinned copy makes room for a new one.
 */
export class ClipHistory {
  private clips: StoredClip[] = [];

  constructor(private readonly file: string, private readonly now: () => number = Date.now) {
    try {
      const parsed = JSON.parse(readFileSync(file, 'utf8')) as { clips?: StoredClip[] };
      this.clips = Array.isArray(parsed.clips) ? parsed.clips.filter((c) => c && typeof c.id === 'string' && typeof c.text === 'string') : [];
    } catch { this.clips = []; }
  }

  private save(): void {
    mkdirSync(path.dirname(this.file), { recursive: true });
    const temp = `${this.file}.${process.pid}.tmp`;
    writeFileSync(temp, JSON.stringify({ version: 1, clips: this.clips }));
    renameSync(temp, this.file);
  }

  /** Keep a copy. Returns false for what is never kept: empty, too long, or shaped like a secret. */
  add(text: string, source?: string): boolean {
    if (!text.trim() || text.length > MAX_CLIP_CHARS || looksSecret(text)) return false;
    const existing = this.clips.find((c) => c.text === text);
    if (existing) {
      existing.at = this.now();
      if (source) existing.source = source;
    } else {
      this.clips.push({ id: randomUUID(), text, at: this.now(), ...(source ? { source } : {}) });
    }
    const unpinned = this.clips.filter((c) => !c.pinned).sort((a, b) => b.at - a.at);
    const drop = new Set(unpinned.slice(MAX_CLIPS).map((c) => c.id));
    this.clips = this.clips.filter((c) => !drop.has(c.id));
    this.save();
    return true;
  }

  pin(id: string, pinned: boolean): boolean {
    const clip = this.clips.find((c) => c.id === id);
    if (!clip) return false;
    if (pinned) clip.pinned = true;
    else delete clip.pinned;
    this.save();
    return true;
  }

  remove(id: string): boolean {
    const before = this.clips.length;
    this.clips = this.clips.filter((c) => c.id !== id);
    if (this.clips.length === before) return false;
    this.save();
    return true;
  }

  /** Pinned first, then newest; each with what it is and what it can become. */
  view(enabled: boolean): ClipView {
    const ordered = [...this.clips].sort((a, b) => Number(!!b.pinned) - Number(!!a.pinned) || b.at - a.at).slice(0, CLIPS_SHOWN);
    return { t: 'clips', enabled, items: ordered.map((c) => ({ id: c.id, pinned: !!c.pinned, ...(c.source ? { source: c.source } : {}), ...classify(c.text) })) };
  }
}
